/**
 * SyncTeX Parser - Bidirectional source/PDF synchronization
 *
 * SyncTeX is a file format generated by pdflatex/xelatex that maps
 * source file positions (line numbers) to PDF page positions (coordinates),
 * enabling forward sync (editor → PDF) and inverse sync (PDF → editor).
 *
 * File format: Plain text with records like:
 * - "Input:N:filename" - maps input number N to filename
 * - "{N" - begin page N (1-indexed)
 * - "[N,X,Y" - begin hbox at (X,Y) from input line N
 * - "(N,X,Y" - begin vbox at (X,Y) from input line N
 * - "hN:X,Y:W,H,D" - horizontal kern/glue at position
 * - "xN:X,Y" - position marker for line N
 * - Coordinates in scaled points (1 sp = 1/65536 pt)
 */

// 1 TeX point = 65536 scaled points
// 1 inch = 72.27 TeX points (NOT 72 — that's PostScript/PDF points)
const SP_PER_PT = 65536
const TEX_PT_PER_INCH = 72.27
const PDF_PT_PER_INCH = 72

/** Source location in the editor */
export interface SourceLocation {
  filename: string
  line: number
  column?: number
}

/** PDF location in PDF-point coordinates (72 DPI, origin top-left) */
export interface PdfLocation {
  page: number    // 1-indexed
  x: number       // PDF points from left edge
  y: number       // PDF points from top edge
  width?: number  // PDF points
  height?: number // PDF points
}

/** Internal record for a sync point */
export interface SyncRecord {
  inputNumber: number
  line: number
  page: number
  x: number  // scaled points
  y: number  // scaled points
  width?: number
  height?: number
  depth?: number
}

/** Parsed SyncTeX data */
export interface SyncTexData {
  inputs: Map<number, string>  // input number → filename
  records: SyncRecord[]
  magnification: number
  xOffset: number
  yOffset: number
  unitLength: number
}

/**
 * Parse SyncTeX data from raw string
 */
export function parseSyncTeX(data: string): SyncTexData | null {
  if (!data || data.length === 0) return null

  const inputs = new Map<number, string>()
  const records: SyncRecord[] = []
  let magnification = 1000  // default 1000 = 1x
  let xOffset = 0
  let yOffset = 0
  let unitLength = 1  // default unit

  let currentPage = 0

  const lines = data.split('\n')

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed) continue

    // Parse header values
    if (trimmed.startsWith('Magnification:')) {
      magnification = parseInt(trimmed.substring(14)) || 1000
      continue
    }
    if (trimmed.startsWith('X Offset:')) {
      xOffset = parseInt(trimmed.substring(9)) || 0
      continue
    }
    if (trimmed.startsWith('Y Offset:')) {
      yOffset = parseInt(trimmed.substring(9)) || 0
      continue
    }
    if (trimmed.startsWith('Unit:')) {
      unitLength = parseInt(trimmed.substring(5)) || 1
      continue
    }

    // Input file mapping: "Input:N:filename"
    const inputMatch = trimmed.match(/^Input:(\d+):(.+)$/)
    if (inputMatch) {
      const num = parseInt(inputMatch[1])
      const filename = inputMatch[2]
      inputs.set(num, filename)
      continue
    }

    // Page begin: "{N" where N is page number
    const pageMatch = trimmed.match(/^\{(\d+)/)
    if (pageMatch) {
      currentPage = parseInt(pageMatch[1])
      continue
    }

    // Page end: "}"
    if (trimmed === '}') {
      continue
    }

    // Horizontal box: "[input,line:x,y:W,H,D" - actual SyncTeX format
    const hboxMatch = trimmed.match(/^\[(\d+),(\d+):(-?\d+),(-?\d+)(?::(-?\d+),(-?\d+),(-?\d+))?/)
    if (hboxMatch && currentPage > 0) {
      const inputNum = parseInt(hboxMatch[1])
      const line = parseInt(hboxMatch[2])
      const x = parseInt(hboxMatch[3])
      const y = parseInt(hboxMatch[4])
      const width = hboxMatch[5] ? parseInt(hboxMatch[5]) : undefined
      const height = hboxMatch[6] ? parseInt(hboxMatch[6]) : undefined
      const depth = hboxMatch[7] ? parseInt(hboxMatch[7]) : undefined

      records.push({
        inputNumber: inputNum,
        line,
        page: currentPage,
        x,
        y,
        width,
        height,
        depth
      })
      continue
    }

    // Vertical box: "(input,line:x,y:W,H,D" - actual SyncTeX format
    const vboxMatch = trimmed.match(/^\((\d+),(\d+):(-?\d+),(-?\d+)(?::(-?\d+),(-?\d+),(-?\d+))?/)
    if (vboxMatch && currentPage > 0) {
      const inputNum = parseInt(vboxMatch[1])
      const line = parseInt(vboxMatch[2])
      const x = parseInt(vboxMatch[3])
      const y = parseInt(vboxMatch[4])
      const width = vboxMatch[5] ? parseInt(vboxMatch[5]) : undefined
      const height = vboxMatch[6] ? parseInt(vboxMatch[6]) : undefined
      const depth = vboxMatch[7] ? parseInt(vboxMatch[7]) : undefined

      records.push({
        inputNumber: inputNum,
        line,
        page: currentPage,
        x,
        y,
        width,
        height,
        depth
      })
      continue
    }

    // Glue/kern: "hinput,line:x,y:w,h,d" - actual SyncTeX format
    const glueMatch = trimmed.match(/^[hgk](\d+),(\d+):(-?\d+),(-?\d+)(?::(-?\d+),(-?\d+),(-?\d+))?/)
    if (glueMatch && currentPage > 0) {
      const inputNum = parseInt(glueMatch[1])
      const line = parseInt(glueMatch[2])
      const x = parseInt(glueMatch[3])
      const y = parseInt(glueMatch[4])
      const width = glueMatch[5] ? parseInt(glueMatch[5]) : undefined
      const height = glueMatch[6] ? parseInt(glueMatch[6]) : undefined
      const depth = glueMatch[7] ? parseInt(glueMatch[7]) : undefined

      records.push({
        inputNumber: inputNum,
        line,
        page: currentPage,
        x,
        y,
        width,
        height,
        depth
      })
      continue
    }

    // Position marker / void vbox / math: "xinput,line:x,y", "vinput,line:x,y", "$input,line:x,y"
    const posMatch = trimmed.match(/^[xv$](\d+),(\d+):(-?\d+),(-?\d+)/)
    if (posMatch && currentPage > 0) {
      const inputNum = parseInt(posMatch[1])
      const line = parseInt(posMatch[2])
      const x = parseInt(posMatch[3])
      const y = parseInt(posMatch[4])

      records.push({
        inputNumber: inputNum,
        line,
        page: currentPage,
        x,
        y
      })
      continue
    }
  }

  // Apply magnification to unit length
  const effectiveUnit = (unitLength * magnification) / 1000

  return {
    inputs,
    records,
    magnification,
    xOffset,
    yOffset,
    unitLength: effectiveUnit,
  }
}

/**
 * Convert scaled points to PDF points (72 DPI coordinate space)
 * Two-stage: sp → TeX points (72.27/inch) → PDF points (72/inch)
 */
function spToPdfPoints(sp: number, unitLength: number): number {
  const texPoints = (sp * unitLength) / SP_PER_PT
  // Convert TeX points to inches, then to PDF points
  return (texPoints / TEX_PT_PER_INCH) * PDF_PT_PER_INCH
}

/**
 * Convert PDF points to scaled points
 */
function pdfPointsToSp(pdfPts: number, unitLength: number): number {
  const texPoints = (pdfPts / PDF_PT_PER_INCH) * TEX_PT_PER_INCH
  return (texPoints * SP_PER_PT) / unitLength
}

/**
 * Forward sync: Find PDF location for a source line
 * Returns coordinates in PDF points (72 DPI, origin top-left)
 * @param _pageHeightPts Retained for call-site compatibility; SyncTeX coordinates are page-height independent.
 */
export function forwardSync(
  syncData: SyncTexData,
  line: number,
  filename?: string,
  _pageHeightPts: number = 792,
): PdfLocation | null {
  if (!syncData || syncData.records.length === 0) return null

  // Find input number for filename
  let targetInput = 1
  if (filename) {
    for (const [num, name] of syncData.inputs) {
      if (name === filename || name.endsWith('/' + filename) || name.endsWith('\\' + filename)) {
        targetInput = num
        break
      }
    }
  }

  // Find records for this line (or closest line)
  let bestRecord: SyncRecord | null = null
  let bestDistance = Infinity

  for (const record of syncData.records) {
    if (record.inputNumber !== targetInput) continue

    const distance = Math.abs(record.line - line)
    if (distance < bestDistance) {
      bestDistance = distance
      bestRecord = record
    }
    if (distance === 0) break
  }

  if (!bestRecord) return null

  // Convert sp to PDF points
  const x = spToPdfPoints(bestRecord.x + syncData.xOffset, syncData.unitLength)
  // SyncTeX records already use a top-left origin, unlike native PDF coordinates.
  const y = spToPdfPoints(bestRecord.y + syncData.yOffset, syncData.unitLength)

  return {
    page: bestRecord.page,
    x: Math.max(0, x),
    y: Math.max(0, y),
    width: bestRecord.width ? spToPdfPoints(bestRecord.width, syncData.unitLength) : undefined,
    height: bestRecord.height ? spToPdfPoints(bestRecord.height, syncData.unitLength) : undefined
  }
}

/**
 * Inverse sync: Find source line for a PDF click position
 * Coordinates are in PDF points (72 DPI, origin top-left)
 * @param _pageHeightPts Retained for call-site compatibility; SyncTeX coordinates are page-height independent.
 */
export function inverseSync(
  syncData: SyncTexData,
  page: number,
  x: number,
  y: number,
  _pageHeightPts: number = 792,
): SourceLocation | null {
  if (!syncData || syncData.records.length === 0) return null

  // Convert PDF-point click position to scaled points
  const xSp = pdfPointsToSp(x, syncData.unitLength) - syncData.xOffset
  const ySp = pdfPointsToSp(y, syncData.unitLength) - syncData.yOffset

  // Find closest record on this page
  let bestRecord: SyncRecord | null = null
  let bestDistance = Infinity

  for (const record of syncData.records) {
    if (record.page !== page) continue

    const dx = record.x - xSp
    const dy = record.y - ySp
    // Weight X less — vertical distance matters more for line matching
    const distance = Math.sqrt(dx * dx * 0.1 + dy * dy)

    if (distance < bestDistance) {
      bestDistance = distance
      bestRecord = record
    }
  }

  if (!bestRecord) return null

  const filename = syncData.inputs.get(bestRecord.inputNumber) || 'document.tex'
  return { filename, line: bestRecord.line }
}

/**
 * Get total number of pages in the document
 */
export function getPageCount(syncData: SyncTexData): number {
  if (!syncData || syncData.records.length === 0) return 0
  return Math.max(...syncData.records.map(r => r.page))
}

/**
 * Get the dominant/median source line for a given page
 * Used for scroll sync: when viewing page N, what line should the editor show?
 */
export function getPageCenterLine(syncData: SyncTexData, page: number): number | null {
  if (!syncData || syncData.records.length === 0) return null

  // Get all lines for this page
  const linesOnPage = syncData.records
    .filter(r => r.page === page)
    .map(r => r.line)

  if (linesOnPage.length === 0) return null

  // Return median line (middle of the page content)
  linesOnPage.sort((a, b) => a - b)
  const midIndex = Math.floor(linesOnPage.length / 2)
  return linesOnPage[midIndex]
}

/**
 * Get line range for a page (first and last lines)
 */
export function getPageLineRange(syncData: SyncTexData, page: number): { first: number; last: number } | null {
  if (!syncData || syncData.records.length === 0) return null

  const linesOnPage = syncData.records
    .filter(r => r.page === page)
    .map(r => r.line)

  if (linesOnPage.length === 0) return null

  return {
    first: Math.min(...linesOnPage),
    last: Math.max(...linesOnPage)
  }
}
